window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-31901\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πελίας, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1583 na letra π · nº geral 31901</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Pélias, filho de Posidão.</p></section></article>\n<article id=\"entry-dgp-31902\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πελιδνός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1584 na letra π · nº geral 31902</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lívido.</p></section></article>\n<article id=\"entry-dgp-31903\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πελίης</h1><div class=\"entry-meta\"><span>DGP · ordem 1585 na letra π · nº geral 31903</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = Πελίας.</p></section></article>\n<article id=\"entry-dgp-31904\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πελιτνός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1586 na letra π · nº geral 31904</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = πελιδνός. 〈πελός〉</p></section></article>\n<article id=\"entry-dgp-31905\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέλλα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1587 na letra π · nº geral 31905</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 recipiente para a ordenha; balde ♦ ἡ Πέλλα 2 Pela, cidade da Macedônia.</p></section></article>\n<article id=\"entry-dgp-31906\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πελληνεύς, έως</h1><div class=\"entry-meta\"><span>DGP · ordem 1588 na letra π · nº geral 31906</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) de Pelene. 〈Πελλήνη〉</p></section></article>\n<article id=\"entry-dgp-31907\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πελλήνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1589 na letra π · nº geral 31907</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Pelene, n. de cidade da Acaia e da Lacônia.</p></section></article>\n<article id=\"entry-dgp-31908\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πελλός</h1><div class=\"entry-meta\"><span>DGP · ordem 1590 na letra π · nº geral 31908</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e πέλλος, η, ον escuro; enegrecido; negro.</p></section></article>\n<article id=\"entry-dgp-31909\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέλμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1591 na letra π · nº geral 31909</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 planta dos pés 2 sola de sapato 3 extremidade 4 Bot. pecíolo. 〈πέλω〉</p></section></article>\n<article id=\"entry-dgp-31910\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέλομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1592 na letra π · nº geral 31910</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. πέλω.</p></section></article>\n<article id=\"entry-dgp-31911\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πελόπειος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1593 na letra π · nº geral 31911</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Pélope: ἡ Π. χθών sóf. a terra de Pélope, o Peloponeso. 〈Πέλοψ〉</p></section></article>\n<article id=\"entry-dgp-31912\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πελοπηιάδαι, ῶν (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1594 na letra π · nº geral 31912</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">os Pelópidas, descendentes de Pélope. 〈Πελοπήιος〉</p></section></article>\n<article id=\"entry-dgp-31913\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πελοπήιος</h1><div class=\"entry-meta\"><span>DGP · ordem 1595 na letra π · nº geral 31913</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = Πελόπειος.</p></section></article>\n<article id=\"entry-dgp-31914\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πελοπίδης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1596 na letra π · nº geral 31914</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 filho ou descendente de Pélope 2 pl. os Pelópidas, descendentes de Pélope. 〈Πέλοψ〉</p></section></article>\n<article id=\"entry-dgp-31915\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πελόπιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1597 na letra π · nº geral 31915</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Pélope. 〈Πέλοψ〉</p></section></article>\n<article id=\"entry-dgp-31916\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πελοποννησιακός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1598 na letra π · nº geral 31916</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 do Peloponeso ♦ τὰ Πελοπον­νησιακά 2 Guerra do Peloponeso. 〈Πελοπόννησος〉</p></section></article>\n<article id=\"entry-dgp-31917\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πελοποννήσιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1599 na letra π · nº geral 31917</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 do Peloponeso; peloponésio ♦ ὁ Πελοποννήσιος 2 habitante do Peloponeso. 〈Πελο­πόννησος〉</p></section></article>\n<article id=\"entry-dgp-31918\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πελοπόννησος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1600 na letra π · nº geral 31918</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Peloponeso, península meridional da Grécia. 〈Πέλοψ, νῆσος〉</p></section></article>\n<article id=\"entry-dgp-31919\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πέλοψ, οπος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1601 na letra π · nº geral 31919</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Pélope, filho de Tântalo.</p></section></article>\n<article id=\"entry-dgp-31920\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πελτάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1602 na letra π · nº geral 31920</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">servir como peltasta, i.e., na infantaria ligeira.</p></section></article>\n<article id=\"entry-dgp-31921\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πελτάριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1603 na letra π · nº geral 31921</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dim. de πέλτη.</p></section></article>\n<article id=\"entry-dgp-31922\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πελταστής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1604 na letra π · nº geral 31922</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">peltasta, soldado da infantaria ligeira armado com um πέλτη. 〈πελτάζω〉</p></section></article>\n<article id=\"entry-dgp-31923\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πελταστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1605 na letra π · nº geral 31923</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 do peltasta 2 hábil no uso do escudo leve ♦ ἡ πελταστική 3 arte de manejar o escudo leve ♦ τὸ πελταστικόν 4 os peltastas; a infantaria ligeira. 〈πελταστής〉</p></section></article>\n<article id=\"entry-dgp-31924\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πελταστικώτατα</h1><div class=\"entry-meta\"><span>DGP · ordem 1606 na letra π · nº geral 31924</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. superl. como os peltastas mais hábeis.</p></section></article>\n<article id=\"entry-dgp-31925\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέλτη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1607 na letra π · nº geral 31925</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pequeno escudo leve para uso da infantaria ligeira 2 dardo longo; lança.</p></section></article>\n<article id=\"entry-dgp-31926\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πελτοφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1608 na letra π · nº geral 31926</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">armado de escudo leve. 〈πέλτη, φέρω〉</p></section></article>\n<article id=\"entry-dgp-31927\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πελῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1609 na letra π · nº geral 31927</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de πελάζω.</p></section></article>\n<article id=\"entry-dgp-31928\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέλω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1610 na letra π · nº geral 31928</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ger. méd. πέλομαι (só pres., impf. ἔπελον, ép. πέλον, aor.2 3ª sing. ép. ἔπλε; méd. aor.2 2ª sing. ἔπλευ, 3ª sing. ἔπλετο, part. πλόμενος) 1 manifestar-se; produzir-se; realizar-se; passar a ser: ὅτε δὴ Πυλίων καὶ Ἐπειῶν ἔπλετο νεῖκος hom. quando então eclodiu a querela entre os pílios e os epeios, κλαγγὴ γεράνων πέλει οὐρανόθι πρό hom. o grito das gruas se eleva ao céu 2 advir de, gen. ou ἐκ e gen.; decorrer; resultar; provir; vir: τοῦ δ’ ἐξ ἀργύρεος ῥυμὸς πέλεν hom. de lá saía um timão de prata, σέο δ’ ἐκ τάδε πάντα πέλονται hom. tudo isso vem de ti, οὐ γάρ τις πρῆξις πέλεται κρυεροῖο γόοιο hom. pois nenhuma ação advém do doloroso pranteio 3 advir para alguém, dat. ou ἐπί e dat.; suceder; ocorrer; atingir: γῆρας καὶ θάνατος, τά τ’ ἐπ’ ἀνθρώποισι πέλονται hom. velhice e morte, coisas que atingem os humanos, νοῦσος ἐπὶ στυγερὴ πέλεται δειλοῖσι βροτοῖσιν hom. uma triste doença atinge os pobres mortais, τῷ δ’ ἤδη ἑνδεκάτη πέλεν ἠὼς οἰχομένῳ hom. a décima aurora surgia para aquele que tinha partido, i. e., ele tinha partido há nove dias 4 com predic. do suj., tornar-se; passar a ser; ficar: ῥεῖα τ’ ἀριγνώτη πέλεται hom. [Ártemis] é facilmente reconhecível, ἀπὸ κροτάφων πελόμεσθα πάντες γηραλέοι teócr. todos nós nos tornamos velhos a partir das têmporas, τριηκόσιοί τε καὶ ἐξήκοντα πέλοντο hom. eles eram trezentos e sessenta, ὀϊζυρὸς περὶ πάντων ἔπλεο hom. o mais infeliz de todos te tornaste, i.e., és o mais infeliz de todos, ἐμεῖο λελασμένος ἔπλευ; hom. esqueceste de mim?</p></section></article>\n<article id=\"entry-dgp-31929\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέλωρ</h1><div class=\"entry-meta\"><span>DGP · ordem 1611 na letra π · nº geral 31929</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">só nom. e gen. sing. (τό) ente prodigioso; prodígio; monstro.</p></section></article>\n<article id=\"entry-dgp-31930\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πελώριος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 1612 na letra π · nº geral 31930</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, poét., ος, ον 1 colossal; extraordinário; prodigioso; monstruoso; assustador ♦ τὰ πελώρια 2 prodígios: τὰ πρὶν δὲ πελώρια ésql. os prodígios de outrora 3 festas das colheitas, em honra a Zeus, na Tessália. 〈πέλωρ〉</p></section></article>\n<article id=\"entry-dgp-31931\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πελωρίς, ίδος</h1><div class=\"entry-meta\"><span>DGP · ordem 1613 na letra π · nº geral 31931</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) 1 do cabo Peloron ♦ ἡ Πελωρίς 2 = Πέλωρον. 〈Πέλωρον〉</p></section></article>\n<article id=\"entry-dgp-31932\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέλωρον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1614 na letra π · nº geral 31932</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 coisa colossal, prodígio, portento; monstro ♦ τὸ Πέλωρον 2 Peloron, promontório ao norte da Sicília. 〈πέλωρ〉</p></section></article>\n<article id=\"entry-dgp-31933\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέλωρος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 1615 na letra π · nº geral 31933</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον colossal; imenso; prodigioso; portentoso; monstruoso. 〈πέλωρ〉</p></section></article>\n<article id=\"entry-dgp-31934\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέμμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1616 na letra π · nº geral 31934</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bolo; doce 2 pl. guloseimas.</p></section></article>\n<article id=\"entry-dgp-31935\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεμματουργός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1617 na letra π · nº geral 31935</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">confeiteiro. 〈πέμμα, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-31936\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεμπάδαρχος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1618 na letra π · nº geral 31936</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comandante de cinco homens. 〈πεμπάς, ἄρχω〉</p></section></article>\n<article id=\"entry-dgp-31937\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεμπάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1619 na letra π · nº geral 31937</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 contar nos cinco dedos; contar (os votos) 2 reconsiderar; repensar ♦ méd. 3 calcular para si; contar para si 4 contar de novo; recontar. 〈πεμπάς〉</p></section></article>\n<article id=\"entry-dgp-31938\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεμπάς, άδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1620 na letra π · nº geral 31938</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 o número cinco 2 grupo de cinco (pessoas ou coisas). 〈πέμπε〉</p></section></article>\n<article id=\"entry-dgp-31939\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεμπαστής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1621 na letra π · nº geral 31939</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que conta, que calcula. 〈πεμπάζω〉</p></section></article>\n<article id=\"entry-dgp-31940\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέμπε</h1><div class=\"entry-meta\"><span>DGP · ordem 1622 na letra π · nº geral 31940</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">eól. = πέντε.</p></section></article>\n<article id=\"entry-dgp-31941\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεμπέμεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1623 na letra π · nº geral 31941</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e πεμπέμεναι inf. pres. ép., πέμπεσκε 3ª sing. impf. iter., de πέμπω.</p></section></article>\n<article id=\"entry-dgp-31942\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεμπταῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1624 na letra π · nº geral 31942</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que ocorre ou chega no 5º dia 2 que ocorre há cinco dias 3 que dura cinco dias (febre). 〈πέμπτος〉</p></section></article>\n<article id=\"entry-dgp-31943\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεμπτέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1625 na letra π · nº geral 31943</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de πέμπω.</p></section></article>\n<article id=\"entry-dgp-31944\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέμπτος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1626 na letra π · nº geral 31944</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 quinto: ἐγὼ πέμπτος μετὰ τοῖσιν hom. eu o quinto entre eles, i.e., com quatro outros, πέμπτη σπιθαμή her. duas varas e meia ♦ ἡ πέμπτη 2 o quinto dia. 〈πέντε〉</p></section></article>\n<article id=\"entry-dgp-31945\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεμπτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1627 na letra π · nº geral 31945</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">enviado. 〈πέμπω〉</p></section></article>\n<article id=\"entry-dgp-31946\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέμπω</h1><div class=\"entry-meta\"><span>DGP · ordem 1628 na letra π · nº geral 31946</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἔπεμπον, fut. πέμψω, aor. ἔπεμψα, perf. πέπομφα, m.-q.-perf. ἐπεπόμφειν; méd. πέμπομαι, aor. ἐπεμψάμην; pas. fut. πεμφθήσομαι, aor. ἐπέμφθην, perf. πέπεμμαι, πέπεμψαι, πέπεμπται etc., m.-q.-perf. ἐπεπέμμην) ativa 1 enviar; despachar algo ou alguém, ac., para um lugar, ac. ou εἰς e ac.; para junto de alguém, εἰς, πρός ou ὡς e ac.; em busca de algo ou alguém, ἐπί e ac.; com inf. ou part. de finalidade 2 mandar de volta; fazer ou deixar partir; devolver; despedir; partic. mandar de volta para casa; devolver a sua pátria 3 mandar dizer; enviar mensageiro para dizer algo, inf., a alguém, dat. 4 escoltar; acompanhar; participar de escolta em honra de alguém, dat. média 5 buscar junto a alguém; mandar vir, ac. 6 enviar algo ou alguém (que lhe pertence), ac. 1 π. ἀγγέλους φήμας καὶ ἐνύπνια καὶ οἰωνούς xen. enviar como mensageiros notícias, boatos, sonhos e presságios, ἐξικέτευσε ἀγρούς σφε πέμψαι sóf. implorou que eu o enviasse para o campo, πέμπε δέ μ’ ἐς Τροίην hom. enviou-me para Tróia, κραιπνοφόροι δέ μ’ ἔπεμψαν αὖραι ésql. céleres despacharam-me as brisas, ἡμᾶς ὁ τήνδε τὴν ὁδὸν πέμπων sóf. aquele que nos envia para este caminho, i.e., que nos despacha para esta viagem, πέμπουσιν οὕτω τὴν Σαλαμινίαν ναῦν ἐς τὴν Σικελίαν ἐπί τε ἐκεῖνον tuc. enviam, desse modo, a nau Salamínia para a Sicília em busca dele [Alcibíades], π. περὶ συμμαχίας xen. enviar para tratar de uma aliança, π. περὶ σπονδῶν xen. enviar para negociar uma trégua, με πέμπει πατρὶ τυμβεῦσαι χοάς sóf. envia-me para fazer libações no túmulo de meu pai, ἄλλον πέμπωμεν ἱκανέμεν hom. despachemo-[los] para irem a outro hóspede, [πρέσβεις, ἄγγελον etc.] πέμπει κελεύων tuc. ele envia uma ordem, πέμπων ἐκέλευε xen. ele enviava uma ordem 2 χρὴ ξεῖνον παρεόντα φιλεῖν, ἐθέλοντα δὲ πέμπειν hom. é preciso ter o hóspede como amigo quando está presente, mas deixá-lo partir se ele deseja, τὸν μὲν δὴ Ἀρτεμβάρεα πέμπει her. assim [Astíages] despediu Artembares 3 πέμπεις σῇ δάμαρτι παῖδα σὴν δεῦρ’ ἀποστέλλειν eur. mandas dizer a tua esposa que envie tua filha para cá, πέμπουσιν οἱ ἔφοροι στρατεύεσθαι ἐπὶ Καρίαν xen. os éforos enviam mensageiro ordenando que partam em campanha contra a Cária, ἔπεμπε πρὸς Κῦρον δεόμενος xen. ele enviava mensageiros até Ciro para pedir 4 τὴν μὲν γὰρ Ἀχαιοὶ ἐς Χρύσην πέμπουσιν hom. então os aqueus a [a moça] escoltam para junto de Crises, πομπὴν πέμπειν her. promover uma procissão, π. θρίαμβον plut. conduzir um cortejo triunfal, celebrar um triunfo 5 πῶς δῆτα σ’ ἂν πεμψαίαθ’; sóf. como então te mandariam buscar? τί χρῆμ’ ἐπέμψω τὸν ἐμὸν ἐκ δόμων πόδα; eur. por que razão me mandaste vir de minha casa? 6 πέμψομαί γε θυγατέρα eur. enviarei minha filha.</p></section></article>\n<article id=\"entry-dgp-31947\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεμπώβολον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1629 na letra π · nº geral 31947</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">espeto de cinco pontas (para sacrifícios). 〈πέμπε, ὀβελός〉</p></section></article>\n<article id=\"entry-dgp-31948\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεμψαίατο</h1><div class=\"entry-meta\"><span>DGP · ordem 1630 na letra π · nº geral 31948</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. opt. aor. méd. poét., πεμψέμεναι inf. fut. at. ép., de πέμπω.</p></section></article>\n<article id=\"entry-dgp-31949\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέμψις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1631 na letra π · nº geral 31949</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 envio 2 missão 3 cortejo. 〈πέμπω〉</p></section></article>\n<article id=\"entry-dgp-31950\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πένει</h1><div class=\"entry-meta\"><span>DGP · ordem 1632 na letra π · nº geral 31950</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. pres. ind. de πένομαι.</p></section></article>\n<article id=\"entry-dgp-31951\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενέστατος, πενέστερος</h1><div class=\"entry-meta\"><span>DGP · ordem 1633 na letra π · nº geral 31951</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">superl. e comp. de πένης.</p></section></article>\n<article id=\"entry-dgp-31952\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενέστης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1634 na letra π · nº geral 31952</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 servo; serviçal de, gen. 2 pobre 3 servo assalariado, na Tessália. 〈πένης〉</p></section></article>\n<article id=\"entry-dgp-31953\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πένης, ητος</h1><div class=\"entry-meta\"><span>DGP · ordem 1635 na letra π · nº geral 31953</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc. e n.; comp. πενέστερος, superl. πενέσ­τατος) 1 pobre 2 pobre de; carente de, gen. 〈πένομαι〉</p></section></article>\n<article id=\"entry-dgp-31954\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενθεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1636 na letra π · nº geral 31954</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">πένθος.</p></section></article>\n<article id=\"entry-dgp-31955\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενθείετον</h1><div class=\"entry-meta\"><span>DGP · ordem 1637 na letra π · nº geral 31955</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª dual pres. ind. ép. de πενθέω.</p></section></article>\n<article id=\"entry-dgp-31956\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενθερά, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1638 na letra π · nº geral 31956</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sogra, mãe da esposa. 〈πενθερός〉</p></section></article>\n<article id=\"entry-dgp-31957\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενθερός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1639 na letra π · nº geral 31957</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 parentesco por casamento 2 sogro, pai da mulher ou do marido 3 cunhado 4 genro.</p></section></article>\n<article id=\"entry-dgp-31958\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πενθεύς, εως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1640 na letra π · nº geral 31958</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Penteu, rei de Tebas.</p></section></article>\n<article id=\"entry-dgp-31959\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενθέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1641 na letra π · nº geral 31959</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. πενθήσω, aor. ἐπένθησα, perf. πεπένθηκα; pas. só pres.) 1 chorar; lamentar 2 intr. estar de luto. 〈πένθος〉</p></section></article>\n<article id=\"entry-dgp-31960\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πένθημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1642 na letra π · nº geral 31960</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">luto, tristeza, lamentação. 〈πενθέω〉</p></section></article>\n<article id=\"entry-dgp-31961\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενθήμεναι</h1><div class=\"entry-meta\"><span>DGP · ordem 1643 na letra π · nº geral 31961</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. pres. ép. de πενθέω.</p></section></article>\n<article id=\"entry-dgp-31962\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενθήμερος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1644 na letra π · nº geral 31962</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de cinco dias; κατὰ πενθήμερον ἑκατέρους ἡγεῖσθαι xen. comandar cada um por seu turno, durante cinco dias. 〈πέντε, ἡμέρα〉</p></section></article>\n<article id=\"entry-dgp-31963\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενθημιποδιαῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1645 na letra π · nº geral 31963</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem dois pés e meio. 〈πέντε, ἥμισυς, πούς〉</p></section></article>\n<article id=\"entry-dgp-31964\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενθήμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1646 na letra π · nº geral 31964</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος doloroso; lúgubre. 〈πένθος〉</p></section></article>\n<article id=\"entry-dgp-31965\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενθητήρ, ῆρος</h1><div class=\"entry-meta\"><span>DGP · ordem 1647 na letra π · nº geral 31965</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) que chora; que se lamenta. 〈πενθέω〉</p></section></article>\n<article id=\"entry-dgp-31966\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενθητήριος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1648 na letra π · nº geral 31966</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">do luto; que é sinal de luto. 〈πεν­θητήρ〉</p></section></article>\n<article id=\"entry-dgp-31967\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενθητικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1649 na letra π · nº geral 31967</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. lutuosamente; tristemente. 〈πενθέω〉</p></section></article>\n<article id=\"entry-dgp-31968\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενθήτρια, ας</h1><div class=\"entry-meta\"><span>DGP · ordem 1650 na letra π · nº geral 31968</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) que chora; que pranteia, gen.</p></section></article>\n<article id=\"entry-dgp-31969\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενθικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1651 na letra π · nº geral 31969</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de luto. 〈πένθος〉</p></section></article>\n<article id=\"entry-dgp-31970\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πένθιμος, ος</h1><div class=\"entry-meta\"><span>DGP · ordem 1652 na letra π · nº geral 31970</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e η, ον 1 de luto; fúnebre; lúgubre 2 que está de luto; triste ♦ τὰ πένθιμα 3 traje de luto. 〈πένθος〉</p></section></article>\n<article id=\"entry-dgp-31971\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πένθος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1653 na letra π · nº geral 31971</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 luto por alguém, gen.: π. ἔχειν hom. guardar luto, ἐπὶ πένθει plut. durante o luto, τινὶ πέν­θος τιθέναι hom. ou παρέχειν ésql. ser a causa de um luto para alguém 2 cerimônia de luto: πένθος ποιήσασθαι her. organizar um luto público 3 dor; aflição 4 motivo de tristeza 5 infelicidade; desgraça.</p></section></article>\n<article id=\"entry-dgp-31972\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1654 na letra π · nº geral 31972</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pobreza; indigência; miséria: ἐν πενίᾳ μυρίᾳ εἰμί plat. estou na miséria mais profunda, πενίαν ἀπολείπειν plut. não deixar nada atrás de si 2 falta de, gen. 3 a pobreza, i.e., os pobres ♦ ἡ Πενία 4 Pobreza, person.</p></section></article>\n<article id=\"entry-dgp-31973\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενίη</h1><div class=\"entry-meta\"><span>DGP · ordem 1655 na letra π · nº geral 31973</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = πενία.</p></section></article>\n<article id=\"entry-dgp-31974\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενιχρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1656 na letra π · nº geral 31974</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pobre; indigente; miserável. 〈πένης〉</p></section></article>\n<article id=\"entry-dgp-31975\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πένομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1657 na letra π · nº geral 31975</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf.) 1 intr. realizar um trabalho penoso, cansativo; cansar-se; trabalhar duro 2 executar; realizar; preparar: π. δαῖτα hom. preparar uma refeição 3 ser pobre 4 carecer de, gen.</p></section></article>\n<article id=\"entry-dgp-31976\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεντάγωνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1658 na letra π · nº geral 31976</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que tem cinco ângulos ♦ τὸ πεντάγωνον 2 pentágono, figura geométrica. 〈πέντε, γωνία〉</p></section></article>\n<article id=\"entry-dgp-31977\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενταδραχμία, πεντάδραχμος</h1><div class=\"entry-meta\"><span>DGP · ordem 1659 na letra π · nº geral 31977</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">πεντεδραχμία, πεν­τέδραχμος.</p></section></article>\n<article id=\"entry-dgp-31978\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεντάεθλον, πεντάεθλος</h1><div class=\"entry-meta\"><span>DGP · ordem 1660 na letra π · nº geral 31978</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = πένταθλον, πένταθλος.</p></section></article>\n<article id=\"entry-dgp-31979\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενταετηρικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1661 na letra π · nº geral 31979</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que acontece a cada cinco anos; quinquenal 2 no quinto ano; quadrienal. 〈πεν­ταέτηρος〉</p></section></article>\n<article id=\"entry-dgp-31980\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενταετηρίς, ίδος</h1><div class=\"entry-meta\"><span>DGP · ordem 1662 na letra π · nº geral 31980</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) 1 de cinco anos; que acontece a cada cinco anos ♦ ἡ πενταετηρίς 2 intervalo de cinco anos; período de cinco anos; lustro. 〈πέντε, ἔτος〉</p></section></article>\n<article id=\"entry-dgp-31981\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενταέτηρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1663 na letra π · nº geral 31981</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">πενταετής.</p></section></article>\n<article id=\"entry-dgp-31982\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενταετής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1664 na letra π · nº geral 31982</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de cinco anos; que tem cinco anos de idade 2 que dura cinco anos ♦ πεντάετες adv. 3 por cinco anos. 〈πέντε, ἔτος〉</p></section></article>\n<article id=\"entry-dgp-31983\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενταετία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1665 na letra π · nº geral 31983</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">período ou duração de cinco anos. 〈πενταετής〉</p></section></article>\n<article id=\"entry-dgp-31984\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενταετίς, ίδος</h1><div class=\"entry-meta\"><span>DGP · ordem 1666 na letra π · nº geral 31984</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) de cinco anos de idade.</p></section></article>\n<article id=\"entry-dgp-31985\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πένταθλον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1667 na letra π · nº geral 31985</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pentatlo, conjunto de cinco concursos atléticos: corrida, luta, pugilato, salto, arremesso de disco. 〈πέντε, ἆθλον〉</p></section></article>\n<article id=\"entry-dgp-31986\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πένταθλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1668 na letra π · nº geral 31986</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 praticante do pentatlo 2 vencedor do pentatlo 3 aquele que exerce muitas atividades ao mesmo tempo 4 aquele que quer sobressair-se em tudo. 〈πέντε, ἆθλος〉</p></section></article>\n<article id=\"entry-dgp-31987\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεντάκις</h1><div class=\"entry-meta\"><span>DGP · ordem 1669 na letra π · nº geral 31987</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. cinco vezes. 〈πέντε, -ακις〉</p></section></article>\n<article id=\"entry-dgp-31988\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεντακισμύριοι, αι, α</h1><div class=\"entry-meta\"><span>DGP · ordem 1670 na letra π · nº geral 31988</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cinquenta mil. 〈πεντάκις, μυρίος〉</p></section></article>\n<article id=\"entry-dgp-31989\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεντακισχίλιοι, αι, α</h1><div class=\"entry-meta\"><span>DGP · ordem 1671 na letra π · nº geral 31989</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cinco mil; no sing. πεντακισχιλία ἀσπίς luc. tropa de cinco mil hoplitas. 〈πεντάκις, χίλιοι〉</p></section></article>\n<article id=\"entry-dgp-31990\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεντακοσίαρχος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1672 na letra π · nº geral 31990</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comandante de quinhentos homens. 〈πεντακόσιοι, ἄρχω〉</p></section></article>\n<article id=\"entry-dgp-31991\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεντακόσιοι, αι, α</h1><div class=\"entry-meta\"><span>DGP · ordem 1673 na letra π · nº geral 31991</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 quinhentos ♦ οἱ Πεντακόσιοι 2 o Conselho dos Quinhentos, em Atenas. 〈πέντε, -κοσιος〉</p></section></article>\n<article id=\"entry-dgp-31992\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεντακοσιομέδιμνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1674 na letra π · nº geral 31992</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de renda de quinhentos medimnos de cereais ♦ οἱ πεντακοσιομέδιμνοι 2 atenienses com esse rendimento, que pertencem à 1ª classe dos cidadãos, conforme constituição de Sólon. 〈πεντακόσιοι, μέδιμνος〉</p></section></article>\n<article id=\"entry-dgp-31993\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεντακοσιοστός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1675 na letra π · nº geral 31993</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">num. ord. quingentésimo. 〈πεν­τακόσιοι〉</p></section></article>\n<article id=\"entry-dgp-31994\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεντακυμία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1676 na letra π · nº geral 31994</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">a quinta onda; grande onda; a que supera as outras. 〈πέντε, κῦμα〉</p></section></article>\n<article id=\"entry-dgp-31995\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεντάμηνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1677 na letra π · nº geral 31995</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de cinco meses. 〈πέντε, μήν〉</p></section></article>\n<article id=\"entry-dgp-31996\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεντάπηχυς, υς, υ</h1><div class=\"entry-meta\"><span>DGP · ordem 1678 na letra π · nº geral 31996</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. εος de cinco côvados. 〈πέντε, πῆχυς〉</p></section></article>\n<article id=\"entry-dgp-31997\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενταπλάσιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1679 na letra π · nº geral 31997</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cinco vezes maior; quíntuplo. 〈πέντε, -πλασιος〉</p></section></article>\n<article id=\"entry-dgp-31998\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πενταπλήσιος</h1><div class=\"entry-meta\"><span>DGP · ordem 1680 na letra π · nº geral 31998</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = πενταπλάσιος.</p></section></article>\n<article id=\"entry-dgp-31999\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεντάπολις, εως,</h1><div class=\"entry-meta\"><span>DGP · ordem 1681 na letra π · nº geral 31999</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. ιος (ἡ) pentápole, confederação de cinco cidades. 〈πέντε, πόλις〉</p></section></article>\n<article id=\"entry-dgp-32000\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πεντάπυλα, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 1682 na letra π · nº geral 32000</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Pentapilas, lit. “de cinco portas”, bairro de Siracusa. 〈πέντε, πύλη〉</p></section></article>\n";
